import java.util.*;public class FestSettlementEngine {static class Ticket{String id;double amount;Ticket(String i,double a){id=i;amount=a;}}static class Fest{int next=1001;Map<String,Ticket> tickets=new LinkedHashMap<>();String issue(double amount,String code){double finalPrice=amount;if("FEST10".equals(code))finalPrice*=.9;else if("STUDENT20".equals(code))finalPrice*=.8;String id="TKT-"+next++;tickets.put(id,new Ticket(id,finalPrice));return id;}double settle(){double total=0;for(Ticket t:tickets.values())total+=t.amount;return total;}}public static void main(String[] args){Fest f=new Fest();System.out.println(f.issue(500,"FEST10"));System.out.println(f.issue(800,"STUDENT20"));System.out.printf("Nightly settlement: %.2f%n",f.settle());}}